responseHandlers.jsonataConvertorExpression:
(
  $exists(avionte_add_application_to_nomiation[0].id) ?
  {
    "data": {
      "newStatus": avionte_add_application_to_nomiation[0].jobActivityName,
      "jobId": avionte_add_application_to_nomiation[0].jobId,
      "candidateId": avionte_add_application_to_nomiation[0].talentId,
      "applicationId": avionte_add_application_to_nomiation[0].id
    }
  } :
  (
    $exists(avionte_application_nomiation_stage_change[0].id) ?
    {
      "data": {
        "newStatus": avionte_application_nomiation_stage_change[0].jobActivityName,
        "jobId": avionte_application_nomiation_stage_change[0].jobId,
        "candidateId": avionte_application_nomiation_stage_change[0].talentId,
        "applicationId": avionte_application_nomiation_stage_change[0].id
      }
    } :
    {
      "data": null,
      "errors": [
        {
          "errorCode": $exists(avionte_application_nomiation_stage_change[0].statusCode) ?
            avionte_application_nomiation_stage_change[0].statusCode :
            "500",
          "message": "Error while updating avionte application status.",
          "params": {
            "error": $
          }
        }
      ]
    }
  )
)
